using EEMS.SharedKernel.Domain;namespace EEMS.Modules.Operations.Domain;public sealed class ChecklistItem:Entity<Guid>{private ChecklistItem(){}private ChecklistItem(Guid id,Guid tenantId,Guid checklistId,string requirement){if(tenantId==Guid.Empty||checklistId==Guid.Empty)throw new ArgumentException("Checklist references are required.");Id=id;TenantId=tenantId;ChecklistId=checklistId;Requirement=OperationRules.Text(requirement,300);}public Guid TenantId{get;private set;}public Guid ChecklistId{get;private set;}public string Requirement{get;private set;}=string.Empty;public bool IsComplete{get;private set;}public Guid? CompletedByUserId{get;private set;}public DateTimeOffset? CompletedAtUtc{get;private set;}public static ChecklistItem Create(Guid tenantId,Guid checklistId,string requirement)=>new(Guid.NewGuid(),tenantId,checklistId,requirement);public void Complete(Guid userId){if(userId==Guid.Empty)throw new ArgumentException("User is required.");if(IsComplete)throw new InvalidOperationException("Already completed.");IsComplete=true;CompletedByUserId=userId;CompletedAtUtc=DateTimeOffset.UtcNow;}}
